import{S as e,b as t,c as n,d as r,f as i,i as a,l as o,m as s,o as c,p as l,r as u,t as d,x as f}from"./polymux-BUxaiCCF.js";t();var p=o(`<link rel="icon" type="image/svg+xml"/>`),m=o(`<header class="svelte-202qz9"><a class="brand svelte-202qz9" href="/" aria-label="Polymux home"><img alt="" class="svelte-202qz9"/> <span>Polymux</span></a> <a class="home-link svelte-202qz9" href="/">Back to home</a></header> <main class="svelte-202qz9"><div class="title-block svelte-202qz9"><p class="eyebrow svelte-202qz9">Legal</p> <h1 class="svelte-202qz9">Privacy Policy</h1> <p class="effective svelte-202qz9">Effective 24 August 2026</p></div> <article class="svelte-202qz9"><section class="svelte-202qz9"><h2 class="svelte-202qz9">Overview</h2> <p class="svelte-202qz9">Polymux is a desktop workspace that can connect to your browser, files,
        messages, email, and AI providers when you ask it to. This policy
        explains how the Polymux desktop app and browser extension handle
        information.</p></section> <section class="svelte-202qz9"><h2 class="svelte-202qz9">Information Polymux handles</h2> <h3 class="svelte-202qz9">Browser tab information</h3> <p class="svelte-202qz9">The browser extension makes a local inventory of open-tab metadata,
        including tab titles, URLs, window identifiers, active or pinned state,
        audible state, and last-accessed time. This inventory does not include
        page contents.</p> <h3 class="svelte-202qz9">Assigned-tab content and activity</h3> <p class="svelte-202qz9">When you ask Polymux to work in a specific browser tab, it may read page
        content and perform or observe interactions needed for that task. This
        can include accessibility information, screenshots, navigation, clicks,
        typing, scrolling, console or network information, dialogs, and task
        results. Polymux limits this access to the tab assigned to the task.</p> <h3 class="svelte-202qz9">Connected services</h3> <p class="svelte-202qz9">If you connect a service or AI provider through the desktop app,
        Polymux handles the information required to complete the actions you
        request. The connected provider's own privacy policy also applies to
        information sent to that provider.</p></section> <section class="svelte-202qz9"><h2 class="svelte-202qz9">How information is used</h2> <p class="svelte-202qz9">Polymux uses information only to:</p> <ul class="svelte-202qz9"><li class="svelte-202qz9">identify the app, window, file, conversation, or browser tab you mean;</li> <li class="svelte-202qz9">complete tasks you request and return their results;</li> <li class="svelte-202qz9">maintain secure local connections between the extension and desktop app; and</li> <li class="svelte-202qz9">diagnose errors and protect the reliability and security of the product.</li></ul></section> <section class="svelte-202qz9"><h2 class="svelte-202qz9">Local browser-extension communication</h2> <p class="svelte-202qz9">The extension communicates with the locally installed Polymux desktop
        app through a native-messaging host and a loopback-only service on your
        computer. Open-tab metadata, assigned-tab commands, cursor status, and
        task results stay on your device through these channels. The extension
        does not send browsing data to a hosted Polymux service.</p></section> <section class="svelte-202qz9"><h2 class="svelte-202qz9">Browser permissions</h2> <p class="svelte-202qz9">The extension uses browser permissions to:</p> <ul class="svelte-202qz9"><li class="svelte-202qz9">list tabs and identify the exact tab assigned to Polymux;</li> <li class="svelte-202qz9">communicate with the locally installed desktop app;</li> <li class="svelte-202qz9">refresh its local connection after the browser suspends it;</li> <li class="svelte-202qz9">read and interact with an assigned tab through browser debugging tools; and</li> <li class="svelte-202qz9">display the Polymux badge and cursor on ordinary HTTP and HTTPS pages.</li></ul></section> <section class="svelte-202qz9"><h2 class="svelte-202qz9">Sharing and sale of data</h2> <p class="svelte-202qz9">Polymux does not sell user data. It does not use or transfer user data
        for advertising, creditworthiness, lending, or purposes unrelated to
        the product's disclosed function. Information is shared with a service
        provider only when needed to use a connection you configured or to
        complete an action you requested.</p></section> <section class="svelte-202qz9"><h2 class="svelte-202qz9">Storage, retention, and control</h2> <p class="svelte-202qz9">Browser-tab inventory and connection state are stored locally for the
        desktop app to use. Access to an assigned tab ends when the task
        releases it, the tab closes, the desktop app disconnects, or you disable
        the extension. You can also remove locally stored Polymux data by
        uninstalling the extension or desktop app and deleting its application
        data.</p></section> <section class="svelte-202qz9"><h2 class="svelte-202qz9">Security</h2> <p class="svelte-202qz9">Polymux limits browser control to an identified assigned tab and uses
        local-only communication for the extension-to-desktop connection. No
        system can guarantee absolute security, but Polymux is designed to
        minimise access and keep you in control of connected services.</p></section> <section class="svelte-202qz9"><h2 class="svelte-202qz9">Changes to this policy</h2> <p class="svelte-202qz9">This policy may change as Polymux develops. The effective date above
        will be updated when material changes are published.</p></section> <section class="svelte-202qz9"><h2 class="svelte-202qz9">Contact</h2> <p class="svelte-202qz9">For privacy questions, email <a href="mailto:carlvince@polymux.com" class="svelte-202qz9">carlvince@polymux.com</a>.</p></section></article></main> <footer class="svelte-202qz9"><a class="brand svelte-202qz9" href="/"><img alt="" class="svelte-202qz9"/><span>Polymux</span></a> <span>Privacy Policy</span></footer>`,1);function h(t){var o=m();a(`202qz9`,e=>{var t=p();r(()=>u(t,`href`,d)),n(e,t)});var c=l(o),h=i(c),g=i(h);f(2),e(h),f(2),e(c);var _=s(c,4),v=i(_),y=i(v);f(),e(v),f(2),e(_),r(()=>{u(g,`src`,d),u(y,`src`,d)}),n(t,o)}c(h,{target:document.getElementById(`app`)});